const uint8_t *font8x16_glyph(uint32_t ch)
{
    size_t i;

    if (ch >= 0x20 && ch <= 0x7e) {
        return font_ascii[ch - 0x20];
    }
    for (i = 0; i < sizeof(font_extra) / sizeof(font_extra[0]); i++) {
        if (font_extra[i].ucs == ch || (ch >= 0x80 && ch <= 0xff && font_extra[i].cp437 == ch)) {
            return font_extra[i].rows;
        }
    }
    return font_replacement;
}

const char *font8x16_name(void)
{
    return "spleen";
}
